D={
950102:("pose a threat","**Pose a threat** = ser um perigo; **pose a question** = levantar uma dúvida; **defuse tension** = acalmar o clima.",[("It {{poses a threat}} to safety.","Representa uma ameaça à segurança."),("It {{poses a question}}.","Levanta uma questão."),("He {{defused the tension}}.","Ele acalmou a tensão."),("An {{ominous}} sign.","Um sinal sinistro.")],"“Defuse” (tensão) =",["acalmar/desarmar","difundir","confundir"],0,"Desarmar."),
84245:("Literatura e sociedade","**Literature can give a voice to marginalized people. Novels depict the society that produces them.**",[("{{Literature can give a voice to}} marginalized people.","A literatura pode dar voz a pessoas marginalizadas."),("{{Novels depict}} the society that produces them.","Romances retratam a sociedade que os produz."),("{{A book can reflect}} its time.","Um livro pode refletir sua época."),("{{Fiction challenges assumptions}}.","A ficção desafia suposições.")],"“Marginalized” =",["marginalizado","margem de página só","majoritário"],0,"À margem."),
84246:("Modernismo e experimentação","**Modernist writers experiment with form. A fragmented plot mirrors a broken world. Readers must piece the meaning together.**",[("{{Modernist writers experiment with form}} to capture the mind.","Escritores modernistas experimentam com a forma para captar a mente."),("{{A fragmented plot mirrors}} a broken world.","Um enredo fragmentado espelha um mundo quebrado."),("{{Readers must piece the meaning together}}.","Os leitores devem juntar o significado."),("{{Stream of consciousness}} flows freely.","O fluxo de consciência corre livre.")],"“Fragmented” =",["fragmentado","frágil","fraco"],0,"Fragmentado."),
84247:("Vozes pós-coloniais","**Postcolonial writers reclaim their own stories. For centuries many voices were silenced. Writing can be an act of resistance.**",[("{{Postcolonial writers reclaim}} their own stories.","Escritores pós-coloniais reivindicam suas próprias histórias."),("{{For centuries, many voices were silenced}}.","Por séculos, muitas vozes foram silenciadas."),("{{Writing can be an act of resistance}}.","Escrever pode ser um ato de resistência."),("{{Identity is rewritten}}.","A identidade é reescrita.")],"“Reclaim” =",["retomar/reivindicar","reclamar de queixa só","reciclar"],0,"Retomar."),
84248:("Memória e trauma na ficção","**Trauma can fracture a character's sense of time. The past can haunt the present. Stories can help characters begin to heal.**",[("{{Trauma can fracture}} a character's sense of time.","O trauma pode fraturar o senso de tempo de um personagem."),("{{The past can haunt the present}} in many novels.","O passado pode assombrar o presente em muitos romances."),("{{Stories can help characters begin to heal}}.","Histórias podem ajudar personagens a começar a se curar."),("{{Memory is unreliable}}.","A memória não é confiável.")],"“Haunt” =",["assombrar","caçar","ter"],0,"Assombrar."),
950103:("line up / lord it over","**Line up** = formar fila; **lock away** = guardar com segurança; **lord it over** = agir como superior; **lean on**.",[("{{Line up}} here.","Formem fila aqui."),("{{Lock away}} the jewels.","Guarde as joias com segurança."),("Don't {{lord it over}} me.","Não aja como superior a mim."),("She {{leaned on}} him.","Ela pressionou ele.")],"“Lord it over” =",["tratar como inferior","ser senhor","fazer feudo"],0,"Superioridade."),
84249:("Sátira e comédia social","**Satire uses humor to criticize society. The writer skewers the pretensions of the rich. Exaggeration makes foolish ideas look absurd.**",[("{{Satire uses humor to criticize}} society without fear.","A sátira usa humor para criticar a sociedade sem medo."),("{{The writer skewers}} the pretensions of the rich.","O escritor espeta as pretensões dos ricos."),("{{Exaggeration makes}} foolish ideas look absurd.","O exagero faz ideias tolas parecerem absurdas."),("{{Irony does the heavy lifting}}.","A ironia faz o trabalho pesado.")],"“Skewer” (figurado) =",["criticar duramente","espetar comida só","afiar"],0,"Espetar."),
950104:("pan out / play out","**Pan out** = dar certo no fim; **shake out** = resolver aos poucos; **play out** = desenrolar-se; **wreak havoc**.",[("It {{panned out}}.","Deu certo no fim."),("Let's see how it {{shakes out}}.","Vamos ver como se resolve."),("The scene {{plays out}}.","A cena se desenrola."),("The storm {{wreaked havoc}}.","A tempestade causou estragos.")],"“Wreak havoc” =",["causar estragos","fazer festa","atrapalhar leve"],0,"Estragos."),
84250:("Revisão de cultura","**Culture is a rich web of stories and habits. Recurring themes link different times. To interpret a work, look at form and context.**",[("{{Culture is a rich web}} of stories and habits.","A cultura é uma rica teia de histórias e hábitos."),("{{Recurring themes link}} different times and places.","Temas recorrentes ligam épocas e lugares diferentes."),("{{To interpret a work}}, look at form and context.","Para interpretar uma obra, olhe forma e contexto."),("{{Cultural literacy}} helps.","A alfabetização cultural ajuda.")],"“Web” (figurado) =",["teia","rede social só","tecido"],0,"Teia."),
84251:("Humor britânico","**British humor often relies on understatement. A friendly insult can be a sign of affection. Deadpan delivery hides the joke.**",[("{{British humor often relies on understatement}}.","O humor britânico muitas vezes depende da subestimação."),("{{A friendly insult can be a sign of affection}} in Britain.","Um insulto amigável pode ser sinal de afeto na Grã-Bretanha."),("{{Deadpan delivery hides}} the joke.","A fala sem expressão esconde a piada."),("{{Irony is everywhere}}.","A ironia está em toda parte.")],"“Deadpan” =",["sem expressão","morto de pan","mortal"],0,"Sem expressão."),
84252:("Humor americano","**American humor is often big and direct. Self-deprecating jokes make speakers seem friendly. A good punchline arrives on time.**",[("{{American humor is often big and direct}}.","O humor americano costuma ser grande e direto."),("{{Self-deprecating jokes}} make speakers seem friendly.","Piadas autodepreciativas fazem o orador parecer simpático."),("{{A good punchline arrives}} on time.","Uma boa frase final chega na hora."),("{{Timing is everything}}.","Tempo é tudo.")],"“Self-deprecating” =",["autodepreciativo","autoexplicativo","autossuficiente"],0,"Se diminui."),
84253:("Jogos de palavras","**A pun plays with a double meaning. Wordplay depends on sound and spelling. Puns rarely survive translation.**",[("{{A pun plays with a double meaning}} on purpose.","Um trocadilho brinca com duplo sentido de propósito."),("{{Wordplay depends on sound and spelling}}.","Jogos de palavras dependem de som e grafia."),("{{Puns rarely survive translation}}.","Trocadilhos raramente sobrevivem à tradução."),("{{Groan-worthy}}, but clever.","De dar risada de dor, mas inteligente.")],"“Wordplay” =",["jogo de palavras","jogo de mundo","palavra solta"],0,"Trocadilho."),
950105:("rock the boat","**Rock the boat** = criar problemas; **ruffle feathers** = irritar; **make waves**; **firebrand**.",[("Don't {{rock the boat}}.","Não crie problemas."),("It {{ruffles feathers}}.","Irrita algumas pessoas."),("He doesn't want to {{make waves}}.","Ele não quer causar agitação."),("A bold {{firebrand}}.","Um agitador ousado.")],"“Ruffle feathers” =",["irritar/desagradar","arrepiar penas só","voar"],0,"Irritar."),
84254:("Sarcasmo e tom de voz","**Tone can reverse the meaning. On the page, sarcasm is harder to detect. When unsure, ask what the speaker means.**",[("{{Tone can reverse the meaning}} of a sentence.","O tom pode inverter o sentido de uma frase."),("{{On the page, sarcasm is harder to detect}}.","Na página, o sarcasmo é mais difícil de detectar."),("{{When unsure, ask what the speaker means}}.","Quando em dúvida, pergunte o que o falante quer dizer."),("{{Intonation gives it away}}.","A entonação entrega.")],"“Give away” =",["revelar","dar de graça só","desistir"],0,"Revelar."),
950106:("lump together","**Lump together** = tratar como um só grupo; **mess about** = fazer bobagem; **mill around** = andar sem rumo; **clear up**.",[("Don't {{lump}} them {{together}}.","Não os trate como um só grupo."),("Stop {{messing about}}.","Pare de fazer bobagem."),("People {{mill around}}.","As pessoas andam sem rumo."),("Let's {{clear up}} the kitchen.","Vamos arrumar a cozinha.")],"“Mill around” =",["circular sem rumo","moer","moinho"],0,"Circular."),
84255:("Referências culturais","**Cultural references assume shared knowledge. Calling someone a Scrooge means they are stingy. Explain a reference.**",[("{{Cultural references assume shared knowledge}}.","Referências culturais supõem conhecimento compartilhado."),("{{Calling someone a Scrooge}} means they are stingy.","Chamar alguém de Scrooge significa que é mão-fechada."),("{{Explain a reference}} when in doubt.","Explique uma referência em caso de dúvida."),("{{Not everyone gets the joke}}.","Nem todos pegam a piada.")],"“Scrooge” =",["mão-de-vaca","herói","rico generoso"],0,"Avarento."),
84256:("Cortesia e tabus","**Some topics are taboo in polite conversation. Tactful speakers tiptoe around sensitive subjects. Ask permission before you raise a delicate topic.**",[("{{Some topics are taboo}} in polite conversation.","Alguns assuntos são tabu numa conversa educada."),("{{Tactful speakers tiptoe around}} sensitive subjects.","Falantes tatuosos contornam assuntos sensíveis."),("{{Ask permission before you raise}} a delicate topic.","Peça licença antes de tocar num assunto delicado."),("{{Read the room}}.","Perceba o clima.")],"“Read the room” =",["perceber o clima","ler o quarto","reservar"],0,"Perceber o clima."),
84257:("Sagacidade e troca de farpas","**Dry wit says little and means a lot. A quick retort keeps the banter alive. Banter works only when there is rapport.**",[("{{Dry wit says little}} and means a lot.","O humor seco diz pouco e quer dizer muito."),("{{A quick retort keeps the banter alive}}.","Uma resposta rápida mantém a brincadeira viva."),("{{Banter works only when there is rapport}}.","A troca de farpas só funciona quando há afinidade."),("{{Knowing when to stop}} matters.","Saber a hora de parar importa.")],"“Banter” =",["troca de brincadeiras","banco","banda"],0,"Provocação amigável."),
950107:("vouch for","**Vouch for** = garantir por alguém; **set your mind at ease** = acalmar; **hold your hand** = acompanhar; **give assurance**.",[("I {{vouch for}} him.","Eu respondo por ele."),("This {{sets your mind at ease}}.","Isso tranquiliza."),("I'll {{hold your hand}} through it.","Vou acompanhar você nisso."),("A firm {{assurance}}.","Uma garantia firme.")],"“Vouch for” =",["responder por","evitar","ligar para"],0,"Garantir."),
84258:("Eufemismos entre culturas","**A euphemism softens an unpleasant truth. Cultures choose different euphemisms for death. Euphemisms can hide the truth.**",[("{{A euphemism softens}} an unpleasant truth.","Um eufemismo suaviza uma verdade desagradável."),("{{Cultures choose different euphemisms}} for death.","Culturas escolhem eufemismos diferentes para a morte."),("{{Euphemisms can hide the truth}} when overused.","Eufemismos podem esconder a verdade quando exagerados."),("{{Passed away}} is gentler than died.","“Passed away” é mais suave que “died”.")],"“Euphemism” =",["eufemismo","eufonia","euforia"],0,"Eufemismo."),
84259:("Expressões da cultura pop","**A show jumps the shark when it gets ridiculous. A meme can spread a phrase around the world. Many fans binge a whole season.**",[("{{A show jumps the shark}} when it gets ridiculous.","Uma série perde o rumo quando fica ridícula."),("{{A meme can spread}} a phrase around the world.","Um meme pode espalhar uma frase pelo mundo."),("{{Many fans binge}} a whole season in one weekend.","Muitos fãs maratonam uma temporada num fim de semana."),("{{It went viral}}.","Viralizou.")],"“Jump the shark” =",["perder o rumo (série)","pular tubarão só","nadar"],0,"Decadência."),
950108:("let sleeping dogs lie","**Let sleeping dogs lie** = não mexer em problemas; **play it by ear** = improvisar; **an uphill battle**; **tread lightly**.",[("{{Let sleeping dogs lie}}.","Não mexa em vespeiro."),("We'll {{play it by ear}}.","Vamos improvisar."),("It's {{an uphill battle}}.","É uma batalha difícil."),("{{Tread lightly}}.","Pise com cuidado.")],"“Play it by ear” =",["improvisar","tocar de ouvido só","escutar"],0,"Improvisar."),
84260:("Ler o tom na escrita","**Short clipped sentences often sound angry. Word choice reveals the writer's attitude. Check the context before you judge the tone.**",[("{{Short clipped sentences}} often sound angry.","Frases curtas e secas muitas vezes soam bravas."),("{{Word choice reveals}} the writer's attitude.","A escolha de palavras revela a atitude do autor."),("{{Check the context before you judge}} the tone.","Confira o contexto antes de julgar o tom."),("{{Punctuation matters}}.","A pontuação importa.")],"“Clipped” =",["seco/curto","grampeado","pendurado"],0,"Cortado."),
84261:("Subtexto na conversa","**Subtext is what people mean but do not say. A loaded question hides an accusation. Silence can carry as much meaning as words.**",[("{{Subtext is what people mean but do not say}}.","Subtexto é o que as pessoas querem dizer mas não dizem."),("{{A loaded question hides an accusation}}.","Uma pergunta carregada esconde uma acusação."),("{{Silence can carry as much meaning}} as words.","O silêncio pode carregar tanto sentido quanto palavras."),("{{Read between the lines}}.","Leia nas entrelinhas.")],"“Loaded question” =",["pergunta tendenciosa","pergunta pesada de peso","pergunta recarregada"],0,"Armadilha."),
950109:("black out / keel over","**Black out** = perder a consciência; **keel over** = desabar; **double over** = curvar-se de dor; **break out in a sweat**.",[("He {{blacked out}}.","Ele desmaiou."),("She {{keeled over}}.","Ela desabou."),("He {{doubled over}} in pain.","Ele se curvou de dor."),("I {{broke out in a sweat}}.","Comecei a suar frio.")],"“Keel over” =",["desabar","quilhar","virar barco só"],0,"Desabar."),
84262:("Linguagem diplomática","**Diplomats express concern instead of anger. We urge all parties to show restraint. Careful wording avoids a crisis.**",[("{{Diplomats express concern}} instead of anger.","Diplomatas expressam preocupação em vez de raiva."),("{{We urge all parties to show restraint}} without delay.","Instamos todas as partes a ter contenção sem demora."),("{{Careful wording avoids a crisis}}.","Escolher bem as palavras evita crises."),("{{We regret the decision}}.","Lamentamos a decisão.")],"“Restraint” =",["contenção","restrição de lugar","descanso"],0,"Contenção."),
84263:("Alternar registros","**People switch registers depending on the situation. Slang builds closeness among friends. Formal register is safer at work.**",[("{{People switch registers}} depending on the situation.","As pessoas mudam de registro conforme a situação."),("{{Slang builds closeness}} among friends.","A gíria cria proximidade entre amigos."),("{{Formal register is safer}} at work.","O registro formal é mais seguro no trabalho."),("{{Code-switching}} is natural.","Alternar códigos é natural.")],"“Register” (língua) =",["registro/nível de formalidade","cadastro","caixa"],0,"Registro."),
84264:("Escrita formal ou casual","**Formal emails avoid contractions and slang. Cheers is a casual way to end. We regret to inform you…**",[("{{Formal emails avoid contractions and slang}}.","E-mails formais evitam contrações e gírias."),("{{Cheers}} is a casual way to end a message in Britain.","“Cheers” é um jeito casual de terminar uma mensagem na Grã-Bretanha."),("{{We regret to inform you}} that the post is filled.","Lamentamos informar que a vaga foi preenchida."),("{{Kind regards}} is neutral.","“Kind regards” é neutro.")],"Qual é casual?",["Cheers","Yours faithfully","Sincerely yours"],0,"Cheers."),
84265:("Humor entre línguas","**Humor is often bound to a language. Timing makes a joke travel better. Some jokes need a short explanation.**",[("{{Humor is often bound to a language}}.","O humor costuma estar preso a uma língua."),("{{Timing makes a joke travel better}} on stage.","O ritmo faz a piada viajar melhor no palco."),("{{Some jokes need a short explanation}}.","Algumas piadas precisam de uma breve explicação."),("{{It's lost in translation}}.","Perde-se na tradução.")],"“Lost in translation” =",["perdido na tradução","perdido no tradutor","traduzido bem"],0,"Perdido."),
950110:("nose around / perk up","**Nose around** = bisbilhotar; **palm off** = empurrar algo ruim; **pass over** = ignorar; **perk up** = animar.",[("Don't {{nose around}}.","Não bisbilhote."),("They {{palmed it off}} on me.","Empurraram isso para mim."),("He was {{passed over}} for promotion.","Ele foi preterido na promoção."),("She {{perked up}}.","Ela se animou.")],"“Pass over” (promoção) =",["ser preterido","passar por cima","ultrapassar"],0,"Preterir."),
84266:("Subestimação","**Understatement makes a big thing sound small. A blizzard might be called a bit chilly. Not exactly cheap often means very expensive.**",[("{{Understatement makes a big thing sound small}}.","A subestimação faz uma coisa grande soar pequena."),("A blizzard might be called {{a bit chilly}}.","Uma nevasca pode ser chamada de “um pouco frio”."),("{{Not exactly cheap}} often means very expensive.","“Não exatamente barato” muitas vezes significa muito caro."),("{{Not bad at all}}.","Nada mal.")],"“Not exactly cheap” =",["caro","barato","grátis"],0,"Caro."),
950111:("whip up / stir up","**Whip up** = preparar rápido; **fire up** = acender; **stir up** = provocar; **dig up** = desenterrar.",[("She {{whipped up}} dinner.","Ela preparou o jantar rápido."),("He {{fired up}} the grill.","Ele acendeu a churrasqueira."),("He {{stirs up}} trouble.","Ele provoca confusão."),("They {{dug up}} old files.","Desenterraram arquivos antigos.")],"“Stir up” (problemas) =",["provocar","mexer comida só","misturar"],0,"Provocar."),
84267:("Quando o inglês brinca","**A portmanteau blends two words. Brunch is a blend of breakfast and lunch. English speakers love to coin new words.**",[("{{A portmanteau blends two words}} into one.","Uma palavra-valise junta duas palavras."),("{{Brunch is a blend of}} breakfast and lunch.","Brunch é a fusão de breakfast e lunch."),("{{English speakers love to coin}} new words.","Falantes de inglês adoram cunhar palavras novas."),("{{Hangry}} means hungry and angry.","“Hangry” é hungry + angry.")],"“Portmanteau” =",["palavra-valise","porta-malas","passaporte"],0,"Fusão."),
84268:("Revisão de nuances culturais","**A smile can mean different things. Cultural nuance lives in tone, timing and context. Ask questions rather than assume.**",[("{{A smile can mean different things}} around the world.","Um sorriso pode significar coisas diferentes pelo mundo."),("{{Cultural nuance lives in}} tone, timing and context.","A nuance cultural mora no tom, no momento e no contexto."),("{{Ask questions rather than assume}}.","Pergunte em vez de supor."),("{{Be curious}}, not judgmental.","Seja curioso, não crítico.")],"“Nuance” =",["nuance","nuvem","número"],0,"Nuance."),
84269:("Revisão dos tempos avançados","**By the time I arrived, the film had started. She has been studying since March. By next June, I will have finished.**",[("{{By the time I arrived}}, the film had started.","Quando cheguei, o filme já tinha começado."),("She {{has been studying}} English since March.","Ela estuda inglês desde março."),("By next June, I {{will have finished}} the course.","Até junho, terei terminado o curso."),("I {{had been waiting}} for an hour.","Eu esperava havia uma hora.")],"“Will have finished” =",["terá terminado","terminou","termina"],0,"Futuro perfeito."),
84270:("Revisão de estilo e sintaxe","**Never have I seen such a view. Parallel structures make lists easy to follow. Concise writing cuts every unnecessary word.**",[("{{Never have I seen}} such a view.","Nunca vi tal vista."),("{{Parallel structures}} make lists easy to follow.","Estruturas paralelas facilitam listas."),("{{Concise writing cuts}} every unnecessary word.","A escrita concisa corta toda palavra desnecessária."),("{{Vary your sentence length}}.","Varie o comprimento das frases.")],"“Concise” =",["conciso","concreto","concluído"],0,"Conciso."),
950112:("the more …, the better","**The more …, the better** liga duas mudanças; **in proportion to** = proporcional a; **no sooner … than**.",[("{{The more}} you play, {{the better}} you get.","Quanto mais joga, melhor fica."),("Pay is {{in proportion to}} effort.","O pagamento é proporcional ao esforço."),("{{No sooner had}} he left {{than}} it rained.","Mal ele saiu, choveu."),("{{The sooner}}, the better.","Quanto antes, melhor.")],"“In proportion to” =",["proporcional a","em proporção contra","em porção"],0,"Proporcional."),
950113:("pile into / pitch in","**Pile into** = amontoar-se em; **pipe down** = ficar quieto; **pitch in** = ajudar; **play along** = seguir a brincadeira.",[("We {{piled into}} the car.","Amontoamo-nos no carro."),("{{Pipe down}}!","Fiquem quietos!"),("Everyone {{pitched in}}.","Todos ajudaram."),("I'll {{play along}}.","Vou entrar na brincadeira.")],"“Pitch in” =",["ajudar/contribuir","arremessar","afundar"],0,"Ajudar."),
84271:("Revisão: reportado e atenuado","**She said she had finished. It appears to be a mistake. Prices tend to rise in summer.**",[("She said that she {{had finished}} the report on Monday.","Ela disse que tinha terminado o relatório na segunda."),("It {{appears to be}} a mistake for now.","Parece ser um erro por ora."),("Prices {{tend to rise}} in summer.","Os preços tendem a subir no verão."),("It {{would seem}} so.","Parece que sim.")],"“Tend to” =",["tender a","tentar","tenso"],0,"Tender."),
84272:("Revisão: colocações avançadas","**Raise awareness, reach a consensus, pose a threat, shed light on**.",[("{{Raise awareness}} among young people.","Aumente a conscientização entre jovens."),("The team {{reached a consensus}} at last.","A equipe chegou a um consenso enfim."),("Climate change {{poses a serious threat}}.","A mudança climática representa uma ameaça séria."),("The study {{sheds light on}} the issue.","O estudo esclarece a questão.")],"Qual combina com “consensus”?",["reach","do","play"],0,"Reach."),
84273:("Revisão: phrasal verbs e idioms","**Figure out, put off, break the ice, call it a day**.",[("We need to {{figure out}} the problem.","Precisamos descobrir o problema."),("Do not {{put off}} the decision.","Não adie a decisão."),("A joke can {{break the ice}}.","Uma piada pode quebrar o gelo."),("Let's {{call it a day}}.","Vamos encerrar por hoje.")],"“Put off” =",["adiar","colocar fora","vestir"],0,"Adiar."),
84274:("Escuta de fala rápida","**Gonna, kinda, wanna** e ligações: *I'm gonna call you later.* *People link words and shorten them.*",[("I'm {{gonna}} call you later.","Vou ligar para você depois."),("It's {{kinda}} hard at first.","É meio difícil no começo."),("I {{wanna}} go.","Quero ir."),("People {{link words}} in daily talk.","As pessoas ligam palavras na fala diária.")],"“Kinda” =",["kind of (meio)","kindly","kinds of"],0,"Meio."),
950114:("bear the brunt","**Bear the brunt** = sofrer o pior; **take the heat** = aguentar pressão; **carry the can** = assumir a culpa; **innocent casualty**.",[("She {{bore the brunt}} for you.","Ela sofreu o pior por você."),("He {{took the heat}}.","Ele aguentou a pressão."),("Who {{carries the can}}?","Quem assume a culpa?"),("An {{innocent casualty}}.","Uma vítima inocente.")],"“Carry the can” =",["assumir a culpa","carregar a lata","limpar"],0,"Culpa."),
84275:("Escuta de sotaques","**A Southern drawl stretches the vowels. A Texan twang sounds nasal. Listening to many accents trains your ear.**",[("{{A Southern drawl}} stretches the vowels.","O sotaque arrastado do Sul alonga as vogais."),("{{A Texan twang}} sounds nasal and bright.","O sotaque texano soa nasal e brilhante."),("{{Listening to many accents trains}} your ear.","Ouvir muitos sotaques treina seu ouvido."),("{{Accents vary widely}}.","Sotaques variam muito.")],"“Drawl” =",["fala arrastada","desenho","chamar"],0,"Arrastado."),
950115:("plow into / pounce on","**Plow into** = começar com energia; **pounce on** = atacar de repente; **cry off** = desistir; **limp along**.",[("He {{plowed into}} the work.","Ele mergulhou no trabalho."),("The cat {{pounced on}} the mouse.","O gato saltou sobre o rato."),("She {{cried off}}.","Ela desistiu."),("The economy {{limps along}}.","A economia vai se arrastando.")],"“Cry off” =",["desistir","chorar muito","gritar"],0,"Desistir."),
84276:("Leitura de textos longos","**Skim the text first. The thesis usually appears in the introduction. Infer meaning from context.**",[("{{Skim the text first}} to get the main idea.","Leia por cima primeiro para a ideia principal."),("{{The thesis usually appears}} in the introduction.","A tese costuma aparecer na introdução."),("{{Infer meaning from context}}.","Infira o sentido pelo contexto."),("{{Take notes as you read}}.","Anote enquanto lê.")],"“Infer” =",["inferir","interferir","inserir"],0,"Inferir."),
84277:("Escrita argumentativa","**State your claim clearly. Acknowledge a counterargument before you rebut it. End with a conclusion.**",[("{{State your claim clearly}} in the first paragraph.","Declare sua tese com clareza no primeiro parágrafo."),("{{Acknowledge a counterargument}} before you rebut it.","Reconheça um contra-argumento antes de refutá-lo."),("{{End with a conclusion}} that echoes your claim.","Termine com uma conclusão que ecoe sua tese."),("{{Support each point}} with evidence.","Apoie cada ponto com evidências.")],"“Rebut” =",["refutar","rebater bola só","reduzir"],0,"Refutar."),
84278:("Opinar com nuance","**On balance, I think… Admittedly, the cost is high but… To some extent, I agree.**",[("{{On balance}}, I think the plan is sound.","No geral, acho o plano sólido."),("{{Admittedly}}, the cost is high, but we can manage.","É verdade que o custo é alto, mas dá para administrar."),("{{To some extent}}, I agree with you.","Até certo ponto, concordo com você."),("{{I'm inclined to think}}…","Tendo a pensar que…")],"“To some extent” =",["até certo ponto","em extensão","por extensão"],0,"Parcialmente."),
84279:("Contar histórias","**Suddenly… To my surprise… Eventually, we all laughed.**",[("{{Suddenly}}, a stranger knocked on the window.","De repente, um estranho bateu na janela."),("{{To my surprise}}, he was an old friend.","Para minha surpresa, era um velho amigo."),("{{Eventually}}, we all laughed about it.","Por fim, todos rimos disso."),("{{Little did I know}}…","Eu mal sabia…")],"“Eventually” =",["por fim","eventualmente (talvez)","possivelmente"],0,"Falso cognato."),
950116:("handle with kid gloves","**Handle with kid gloves** = tratar com muito cuidado; **tread carefully**; **don't mince words** = ser direto.",[("{{Handle}} her {{with kid gloves}}.","Trate-a com todo o cuidado."),("{{Tread carefully}} here.","Pise com cuidado aqui."),("Don't {{mince words}}.","Não meça palavras."),("A {{delicate}} case.","Um caso delicado.")],"“Don't mince words” =",["seja direto","não moa palavras","fale baixo"],0,"Franqueza."),
84280:("Vocabulário de precisão","**Precise words replace vague ones. Elated is stronger than happy. Choose the word that fits the mood.**",[("{{Precise words replace vague ones}}.","Palavras precisas substituem as vagas."),("{{Elated is stronger than happy}} in English.","“Elated” é mais forte que “happy”."),("{{Choose the word that fits}} the mood exactly.","Escolha a palavra que combina exatamente com o clima."),("{{Say “exhausted”}}, not “tired”.","Diga “exhausted”, não “tired”.")],"“Elated” =",["muito feliz","cansado","furioso"],0,"Eufórico."),
84281:("Inglês acadêmico","**This study explores the link between… Prior research suggests… The findings are limited by…**",[("{{This study explores the link}} between sleep and memory.","Este estudo explora a ligação entre sono e memória."),("{{Prior research suggests}} a weak relationship.","Pesquisas anteriores sugerem uma relação fraca."),("{{The findings are limited by}} sample size.","Os achados são limitados pelo tamanho da amostra."),("{{Further studies are needed}}.","São necessários mais estudos.")],"“Prior” =",["anterior","prioritário só","privado"],0,"Anterior."),
950117:("shed tears","**Shed tears** = chorar; **hit a snag** = esbarrar num problema; **reach a verdict** = chegar a um veredito.",[("She {{shed tears}}.","Ela derramou lágrimas."),("We {{hit a snag}}.","Esbarramos num problema."),("The jury {{reached a verdict}}.","O júri chegou a um veredito."),("He {{rendered a decision}}.","Ele proferiu uma decisão.")],"“Hit a snag” =",["esbarrar num problema","bater num galho","parar"],0,"Obstáculo."),
84282:("Simulado C1: uso do inglês","**Open cloze**: uma palavra por lacuna. **Word formation**: mude a forma com sufixo.",[("In an open cloze, {{you fill each gap}} with one word.","Num teste de lacunas abertas, você preenche cada lacuna com uma palavra."),("In word formation, {{you change the form}} of a given word.","Em formação de palavras, você muda a forma de uma palavra dada."),("Read the whole text {{before you answer}}.","Leia o texto todo antes de responder."),("{{Check grammar}} and spelling.","Confira gramática e ortografia.")],"“Open cloze” =",["lacunas abertas","fechamento aberto","teste fechado"],0,"Lacunas."),
84283:("Simulado C1: leitura","**Multiple choice** costuma ter distratores; a resposta certa **parafraseia** o texto.",[("{{Multiple choice questions often include a distractor}}.","Questões de múltipla escolha costumam ter distratores."),("{{The correct answer usually paraphrases}} the text.","A resposta certa geralmente parafraseia o texto."),("{{Look for the implied meaning}}.","Procure o sentido implícito."),("{{Eliminate wrong options}} first.","Elimine primeiro as opções erradas.")],"“Distractor” =",["opção enganosa","distrator de atenção só","dicionário"],0,"Distrai."),
950118:("hold off","**Hold off** = conter/adiar; **hold on to** = agarrar-se; **hold court** = ser o centro das atenções.",[("{{Hold off}} the attack.","Segure o ataque."),("{{Hold on to}} your dreams.","Agarre-se aos seus sonhos."),("He {{holds court}}.","Ele é o centro das atenções."),("They {{held out}}.","Eles resistiram.")],"“Hold court” =",["ser o centro das atenções","fazer tribunal só","segurar quadra"],0,"Centro."),
84284:("Simulado C1: escuta","**Listen first for the gist. Signpost words show where the talk is going. Intonation reveals attitude.**",[("{{Listen first for the gist}} of the recording.","Ouça primeiro a ideia geral da gravação."),("{{Signpost words show}} where the talk is going.","Palavras de sinalização mostram para onde vai a fala."),("{{Intonation reveals attitude}} as well.","A entonação também revela atitude."),("{{Note key words}}.","Anote palavras-chave.")],"“Gist” =",["ideia geral","detalhe","resumo curto só"],0,"Essência."),
84285:("Simulado C1: escrita","**The benefits outweigh the drawbacks. Moreover… Nevertheless…**",[("{{The benefits of remote work outweigh the drawbacks}}.","Os benefícios do trabalho remoto superam as desvantagens."),("{{Moreover}}, it saves time and money.","Além disso, economiza tempo e dinheiro."),("{{Nevertheless}}, some people feel isolated.","Mesmo assim, algumas pessoas se sentem isoladas."),("{{In conclusion}}, flexibility wins.","Em conclusão, a flexibilidade vence.")],"“Outweigh” =",["superar","pesar fora","esperar"],0,"Superar."),
84286:("Simulado C1: fala","**I am inclined to agree… Let me look at it from another angle… What I mean is…**",[("{{I am inclined to agree}} with my partner.","Tendo a concordar com meu parceiro."),("{{Let me look at it from another angle}}.","Deixe-me olhar por outro ângulo."),("{{What I mean is}} that cost matters most.","O que quero dizer é que o custo importa mais."),("{{I'd like to add}} something.","Gostaria de acrescentar algo.")],"“Inclined to” =",["propenso a","inclinado fisicamente","incluído"],0,"Propenso."),
950119:("spruce up","**Spruce up** = deixar elegante; **square up** = acertar contas; **shoot down** = rejeitar; **shut out** = excluir.",[("{{Spruce up}} the room.","Arrume o quarto."),("Let's {{square up}}.","Vamos acertar as contas."),("They {{shot down}} the idea.","Eles rejeitaram a ideia."),("They {{shut out}} the critics.","Eles excluíram os críticos.")],"“Shoot down” (ideia) =",["rejeitar","atirar embaixo","abater avião só"],0,"Rejeitar."),
84287:("Revisão: conectivos","**Whereas, despite, consequently**.",[("{{Whereas}} some prefer cities, others love the country.","Enquanto alguns preferem cidades, outros amam o campo."),("{{Despite}} the rain, we enjoyed the trip.","Apesar da chuva, curtimos a viagem."),("Prices rose. {{Consequently}}, fewer bought.","Os preços subiram. Consequentemente, menos pessoas compraram."),("{{Nonetheless}}, we kept going.","Mesmo assim, continuamos.")],"“Consequently” =",["consequentemente","consistentemente","constantemente"],0,"Portanto."),
950120:("jut out / loom over","**Jut out** = projetar-se; **loom over** = elevar-se imponente; **flank** = ladear; **adorn** = enfeitar.",[("It {{juts out}} over the sea.","Projeta-se sobre o mar."),("A tower {{looms over}} the town.","Uma torre se ergue imponente sobre a cidade."),("Statues {{flank}} the door.","Estátuas ladeiam a porta."),("Flowers {{adorn}} the arch.","Flores enfeitam o arco.")],"“Flank” =",["ladear","flutuar","fugir"],0,"Ladear."),
84288:("Revisão: expressões fixas","**By and large, sooner or later, first and foremost**.",[("{{By and large}}, the course was a success.","No geral, o curso foi um sucesso."),("{{Sooner or later}}, we all face change.","Mais cedo ou mais tarde, todos enfrentamos mudança."),("{{First and foremost}}, we need a plan.","Antes de tudo, precisamos de um plano."),("{{Once in a while}}.","De vez em quando.")],"“By and large” =",["no geral","por e grande","de longe"],0,"Em geral."),
84289:("Condicionais formais","**Should you need assistance… Unless payment is received… In the event of a delay…**",[("{{Should you need assistance}}, please contact us.","Caso precise de ajuda, entre em contato."),("{{Unless payment is received}}, the offer will lapse.","A menos que o pagamento seja recebido, a oferta expirará."),("{{In the event of a delay}}, we will inform you.","Em caso de atraso, informaremos."),("{{Provided that}} you comply…","Desde que você cumpra…")],"“Should you need” =",["if you should need","if you need not","you should need"],0,"Inversão."),
84290:("Descrevendo tendências","**Sales declined sharply. They rebounded strongly. Prices surged by 20%.**",[("{{Sales declined sharply}} in the spring.","As vendas caíram bruscamente na primavera."),("{{They rebounded strongly}} in the summer.","Recuperaram-se com força no verão."),("{{Prices surged by}} twenty percent.","Os preços dispararam 20%."),("{{It levelled off}}.","Estabilizou-se.")],"“Rebound” =",["recuperar-se","rebater","reiniciar"],0,"Recuperar."),
84291:("Arrependimento e desejos","**I wish I had studied harder. I should have called earlier. It is not too late to change things.**",[("{{I wish I had studied harder}} before the exam.","Queria ter estudado mais antes da prova."),("{{I should have called earlier}}.","Eu devia ter ligado mais cedo."),("{{It is not too late}} to change things.","Não é tarde demais para mudar as coisas."),("{{If only I had known}}.","Se ao menos eu soubesse.")],"“It's not too late” =",["ainda dá tempo","é tarde demais","nunca"],0,"Ainda dá."),
950121:("draw a line under","**Draw a line under / put to bed** = encerrar um assunto; **rest your case**; **sum up**.",[("Let's {{draw a line under}} it.","Vamos dar o assunto por encerrado."),("We {{put it to bed}}.","Encerramos de vez."),("{{I rest my case}}.","Encerro minha argumentação."),("A brief {{summation}}.","Uma breve síntese.")],"“I rest my case” =",["encerro minha argumentação","descanso minha caixa","durmo"],0,"Argumentação."),
84292:("Certeza e dúvida","**I am absolutely certain… There is little doubt that… It is highly improbable that…**",[("{{I am absolutely certain}} about the date.","Estou absolutamente certo da data."),("{{There is little doubt that}} he will win.","Há pouca dúvida de que ele vai ganhar."),("{{It is highly improbable that}} she will refuse.","É altamente improvável que ela recuse."),("{{I'm not entirely sure}}.","Não tenho certeza total.")],"“Improbable” =",["improvável","impossível","importante"],0,"Improvável."),
950122:("size up / soak up","**Size up** = avaliar; **skim through** = folhear; **soak up** = absorver; **sort through** = vasculhar.",[("He {{sized}} it {{up}}.","Ele avaliou a situação."),("{{Skim through}} the chapter.","Folheie o capítulo."),("{{Soak up}} the sun.","Aproveite o sol."),("{{Sort through}} the papers.","Vasculhe os papéis.")],"“Soak up” =",["absorver","encharcar só","secar"],0,"Absorver."),
84293:("Resumir e parafrasear","**In a nutshell… In other words… A good summary keeps the main idea and drops the details.**",[("{{In a nutshell}}, the speaker rejected the offer.","Em suma, o orador recusou a oferta."),("{{In other words}}, he said no politely.","Em outras palavras, ele disse não com educação."),("{{A good summary keeps the main idea}} and drops the details.","Um bom resumo mantém a ideia principal e corta os detalhes."),("{{Put simply}}…","Dito de modo simples…")],"“In a nutshell” =",["em poucas palavras","numa noz","em uma casca"],0,"Resumindo."),
84294:("Instruções com precisão","**First, make sure the device is switched off. Press the button precisely twice. Proceed with caution.**",[("{{First, make sure}} the device is switched off.","Primeiro, certifique-se de que o aparelho está desligado."),("{{Press the button precisely twice}} as shown.","Aperte o botão exatamente duas vezes, como mostrado."),("{{Proceed with caution}} near the edge.","Prossiga com cautela perto da beirada."),("{{Do not exceed}} the limit.","Não ultrapasse o limite.")],"“Proceed” =",["prosseguir","processar","proceder só"],0,"Prosseguir."),
84295:("E-mails persuasivos","**I am writing to propose a partnership. The arrangement would be mutually beneficial. I would welcome the opportunity to discuss.**",[("{{I am writing to propose}} a partnership.","Escrevo para propor uma parceria."),("{{The arrangement would be mutually beneficial}}.","O arranjo seria mutuamente benéfico."),("{{I would welcome the opportunity to}} discuss it.","Eu apreciaria a oportunidade de discutir isso."),("{{Please let me know}} your thoughts.","Por favor, diga-me o que acha.")],"“Mutually beneficial” =",["benéfico para ambos","mutuamente cego","muito útil só"],0,"Ambos ganham."),
84296:("Escuta ativa","**That sounds really tough. If I understand correctly, you felt ignored. Tell me more.**",[("{{That sounds really tough}}.","Isso parece realmente difícil."),("{{If I understand correctly}}, you felt ignored.","Se entendi bem, você se sentiu ignorado."),("{{Tell me more about what happened}}.","Conte-me mais sobre o que aconteceu."),("{{I hear you}}.","Eu te entendo.")],"“I hear you” aqui =",["entendo o que sente","ouço você alto","ouvi dizer"],0,"Empatia."),
950123:("round off","**Round off** = completar bem; **polish off** = acabar com rapidez; **tie up** = resolver pendências; **wrap up**.",[("{{Round off}} the day with a walk.","Termine bem o dia com uma caminhada."),("He {{polished off}} the pie.","Ele devorou a torta."),("{{Tie up}} loose ends.","Resolva as pendências."),("{{Wrap up}} the meeting.","Encerre a reunião.")],"“Polish off” (comida) =",["acabar rápido","polir","limpar"],0,"Devorar."),
84297:("Último treino variado","**C1 speakers use a wide range of vocabulary. Fluency means speaking with ease. Confidence grows with practice.**",[("{{C1 speakers use a wide range of vocabulary}}.","Falantes C1 usam um vocabulário amplo."),("{{Fluency means speaking with ease}}.","Fluência é falar com facilidade."),("{{Confidence grows with practice}}.","A confiança cresce com a prática."),("{{Keep challenging yourself}}.","Continue se desafiando.")],"“A wide range of” =",["uma ampla variedade de","um largo alcance de","um raio de"],0,"Ampla."),
950124:("speed up / spin off","**Speed up** = acelerar; **spin off** = dar origem a algo; **spill over** = transbordar; **step aside** = afastar-se.",[("{{Speed up}}!","Acelere!"),("It {{spun off}} a new brand.","Deu origem a uma nova marca."),("It {{spilled over}}.","Transbordou."),("He {{stepped aside}}.","Ele se afastou.")],"“Spill over” =",["transbordar","derramar tudo","perder"],0,"Transbordar."),
84298:("Sua jornada no C1","**You have come a long way since A1. Progress is rarely a straight line. Set a new goal.**",[("{{You have come a long way}} since level A1.","Você percorreu um longo caminho desde o nível A1."),("{{Progress is rarely a straight line}}.","O progresso raramente é uma linha reta."),("{{Set a new goal}} to keep moving forward.","Defina uma nova meta para seguir em frente."),("{{Celebrate small wins}}.","Comemore pequenas vitórias.")],"“Come a long way” =",["progredir muito","vir de longe só","viajar"],0,"Progresso."),
84299:("Antes de entrar no C2","**C2 asks you to refine, not just to learn. Precision matters more than quantity. Mastery takes patient daily practice.**",[("{{C2 asks you to refine}}, not just to learn.","O C2 pede que você refine, não só aprenda."),("{{Precision matters more than quantity}}.","Precisão importa mais que quantidade."),("{{Mastery takes patient, daily practice}}.","A maestria exige prática paciente e diária."),("{{Subtlety is key}}.","A sutileza é fundamental.")],"“Refine” =",["refinar","refletir","reformar"],0,"Refinar."),
84300:("Despedida do C1","**Today we say farewell to C1. You have reached an important milestone. Be proud of every step.**",[("{{Today we say farewell}} to level C1.","Hoje nos despedimos do nível C1."),("{{You have reached an important milestone}} this year.","Você alcançou um marco importante este ano."),("{{Be proud of every step}} you took.","Orgulhe-se de cada passo que deu."),("{{See you at C2}}!","Vejo você no C2!")],"“Milestone” =",["marco","milha de pedra","pedra pesada"],0,"Marco."),
950125:("go out with a bang","**Go out with a bang** = sair em grande estilo; **end on a high note** = terminar no auge; **ride off into the sunset**; **swan song**.",[("He {{went out with a bang}}.","Ele saiu em grande estilo."),("Let's {{end on a high note}}.","Vamos terminar no auge."),("They {{ride off into the sunset}}.","Eles partem rumo ao pôr do sol."),("It was her {{swan song}}.","Foi sua despedida.")],"“Swan song” =",["última apresentação","canção de cisne só","música triste"],0,"Despedida."),
}
